      "ar": "هذا الملعب التقليدي في لانكشاير هو أحد الملاعب القليلة المتبقية التي تتميز بمقاعد خشبية في مدرجها الرئيسي التاريخي. فاز الفريق الذي يلعب هنا ببطولة الدوري عام 1960 بتشكيلة كاملة من اللاعبين المحليين. يدعم المشجعون فريقهم بشكل فريد بارتداء اللونين العنابي والأزرق.",
      "es": "Este tradicional campo de Lancashire es uno de los últimos estadios que conserva asientos de madera en su histórica grada principal. El equipo que juega aquí ganó notablemente el campeonato en 1960 con una plantilla íntegramente de jugadores locales. Los aficionados apoyan a su equipo vistiendo clarete y azul.",
      "fr": "Ce terrain traditionnel du Lancashire est l'un des derniers stades à avoir des sièges en bois dans sa tribune principale. L'équipe qui y joue a remporté le championnat en 1960 avec une équipe entièrement composée de joueurs locaux. Les fans soutiennent leur équipe en portant du bordeaux et du bleu.",
      "de": "Dieser traditionelle Platz in Lancashire ist eines der letzten Stadien, das Holzsitze auf seiner historischen Haupttribüne aufweist. Das hier spielende Team gewann 1960 die Meisterschaft mit einem Kader nur aus lokalen Spielern. Die Fans unterstützen ihr Team einzigartig in Weinrot und Blau."
