      "de": "Dieser Ort in East Anglia hat sein Heimteam häufiger zwischen den obersten zwei Ligen pendeln sehen als fast jede andere Mannschaft. Eine berühmte Fernsehköchin war jahrelang die leidenschaftliche Mehrheitseigentümerin des Clubs. Die Stadionfans schwenken gelbe und grüne Schals für ein Team, das nach einem Singvogel benannt ist."
