      "es": "Este asentamiento de West Midlands toma su nombre único de Lady Wulfrun, una noble anglosajona que lo fundó. Su equipo de fútbol local albergó pioneros partidos nocturnos contra equipos europeos en los años 50. Los devotos ciudadanos de esta ciudad abrazan apasionadamente una identidad de lobo oro viejo y negro para su club.",
