      "es": "Este increíblemente peculiar estadio ganó fama mundial porque una entrada para visitantes está construida directamente debajo de una hilera de casas residenciales. Finalmente albergó sus primeros partidos de élite de la era moderna en la temporada 2023-2024. Los aficionados están orgullosos de la conexión histórica de su ciudad con la sombrerería.",
      "fr": "Ce stade incroyablement insolite a acquis une renommée mondiale car une entrée pour les visiteurs est construite directement sous une rangée de maisons. Il a finalement accueilli ses premiers matchs de l'élite de l'ère moderne lors de la saison 2023-2024. Les fans sont fiers du lien historique de leur ville avec la fabrication de chapeaux.",
