      "fr": "Situé à 551 pieds au-dessus du niveau de la mer, ce lieu des Midlands est officiellement le stade le plus élevé de tous les clubs professionnels du pays. Il présente une grande grive assise sur une réplique de ballon de football. Le terrain a connu une 'Grande Évasion' de la relégation le dernier jour de la saison 2004-2005.",
