      "es": "Este ajustado e intimidante campo de la costa sur es el único estadio de fútbol profesional del país ubicado en una isla. Ha mantenido su clásica fachada de entrada principal de estilo simulado Tudor durante décadas. Los aficionados tocan una campana continuamente durante los partidos para animar a sus jugadores vestidos de azul.",
      "fr": "Ce terrain intimidant de la côte sud est le seul stade de football professionnel du pays situé sur une île. Il a conservé sa façade d'entrée classique de style néo-Tudor pendant des décennies. Les fans de ces tribunes sonnent continuellement une cloche tout au long des matchs pour rallier leurs joueurs vêtus de bleu.",
      "de": "Dieser enge Platz an der Südküste ist das einzige Profi-Fußballstadion im ganzen Land, das sich auf einer Insel befindet. Es hat jahrzehntelang seine klassische Pseudo-Tudor-Haupteingangsfassade beibehalten. Die Fans läuten während der Spiele ununterbrochen eine laute Glocke, um ihre blau gekleideten Spieler zu versammeln."
