      "es": "Construido originalmente en 1890 para un deporte estadounidense completamente diferente, este recinto de las Midlands se hizo universalmente famoso por su campo notoriamente embarrado. Un legendario y franco entrenador ganó su primer campeonato de liga en este mismo césped en 1972. El equipo abandonó por completo este histórico hogar en 1997 para mudarse a una arena tipo parque.",
      "fr": "Construit à l'origine en 1890 pour un sport américain totalement différent, ce lieu des Midlands est devenu universellement célèbre pour son terrain notoirement boueux. Un légendaire manager au franc-parler a remporté son tout premier championnat de ligue sur cette même pelouse en 1972. L'équipe a complètement abandonné ce domicile hautement historique en 1997 pour s'installer dans une arène de parc.",
