      "ar": "كان هذا الملعب في ميدلاندز أول ملعب مجهز بالكامل بالمقاعد في جميع أنحاء البلاد في عام 1981. استضاف بفخر كرة القدم في الدرجة الأولى لأكثر من ثلاثين عامًا متواصلة حتى هبوط فريقه أخيرًا في عام 2001. تخلى الفريق المحلي ذو اللون الأزرق السماوي في النهاية عن هذا الملعب التاريخي في عام 2005 للانتقال إلى ساحة حديثة.",
      "es": "Este recinto de las Midlands fue famoso por ser el primer estadio con asientos en todo el país allá por 1981. Albergó con orgullo fútbol de primera división durante más de treinta años ininterrumpidos hasta que su equipo descendió finalmente en 2001. El equipo local celeste abandonó finalmente este histórico campo en 2005 para mudarse a una arena moderna.",
      "fr": "Ce lieu des Midlands a été célèbre pour être le premier stade entièrement équipé de places assises dans tout le pays en 1981. Il a fièrement accueilli le football de l'élite pendant plus de trente ans sans interruption jusqu'à ce que son équipe soit finalement reléguée en 2001. L'équipe locale bleu ciel a finalement abandonné ce terrain historique en 2005 pour s'installer dans une arène moderne.",
