      "de": "Dieses bekanntlich enge und einschüchternde Hauptstadtstadion war die spirituelle Heimat der berüchtigten 'Crazy Gang', die 1988 mit dem Gewinn des FA Cups die Nation schockierte. Es wurde 1991 vom Profifußball komplett aufgegeben, als strenge neue Stadionregeln eingeführt wurden. Jahrzehnte später wurde nur wenige Meter entfernt von Fans ein brandneues Stadion mit demselben historischen Namen gebaut."
