      "de": "Dieses traditionelle Stadion in den East Midlands liegt dramatisch im direkten Schatten einer prächtigen, hoch aufragenden historischen Kathedrale auf einem nahegelegenen Hügel. Das Heimteam schrieb 2017 beispiellose Geschichte, als es als erste Nicht-Liga-Mannschaft seit über einem Jahrhundert auf wundersame Weise das FA-Cup-Viertelfinale erreichte. Die leidenschaftlichen Fans bezeichnen ihr geliebtes rot-weiß gestreiftes Team herzlich als die Imps (Kobolde)."
