      "de": "Dieses hochmoderne Stadion in Northamptonshire wurde 1992 von einem wohlhabenden Schuhmachermillionär erbaut. Es beherbergte kurzzeitig Profifußball für einen schnell aufsteigenden Club, der nach einem Edelstein benannt war, bevor er sich tragisch auflöste. Die verlassene Arena wurde leider 2017 komplett abgerissen, um Platz für einen Freizeitpark zu machen."
