      "es": "Este estadio del noreste, notoriamente helado, era apodado universalmente 'The Vic' y se asienta peligrosamente cerca de la dura costa. El equipo local eligió de manera única a un hombre vestido como una mascota mono para ser el verdadero alcalde de su ciudad. El equipo juega con rayas azules y blancas.",
      "fr": "Ce stade du Nord-Est, notoirement glacial, était universellement surnommé 'The Vic' et se trouve dangereusement près de la côte rude. L'équipe locale a élu de façon unique un homme déguisé en mascotte de singe comme véritable maire de leur ville. L'équipe passionnément soutenue joue en rayures bleues et blanches.",
      "de": "Dieses berüchtigt eiskalte Stadion im Nordosten trug allgemein den Spitznamen 'The Vic' und liegt gefährlich nah an der rauen Küste. Das Heimteam wählte einzigartig einen Mann, der als Affenmaskottchen verkleidet war, zum tatsächlichen Bürgermeister ihrer Stadt. Das leidenschaftlich unterstützte Team spielt in blau-weißen Streifen."
