      "de": "Dieses traditionelle Stadion in Somerset wurde 1990 eröffnet, um einen unglaublich berühmten, stark abfallenden historischen Platz zu ersetzen. Das Heimteam trägt markante grün-weiße Querstreifen und trägt den einzigartigen Spitznamen 'The Glovers' (Die Handschuhmacher). Das Team schaffte 2013 ein erstaunliches modernes Wunder, indem es die zweite Liga erreichte."
