      "fr": "Cette ville historique du West Yorkshire est mondialement célèbre comme le berceau incontesté de la Rugby League en 1895. Son équipe locale de football portait des rayures bleues et blanches et a historiquement remporté trois titres consécutifs de première division dans les années 1920. Les citoyens soutiennent passionnément une équipe surnommée d'après un chien terrier local.",
