      "de": "Dieser historische Platz in Kent dient als Heimat eines professionellen Teams, das historisch mit einer riesigen, weltweit berühmten Fährflotte über den Ärmelkanal verbunden ist. Das rot gekleidete Heimteam erlangte 2008 enorme virale Aufmerksamkeit, als es von einem umstrittenen Online-Projekt gekauft wurde, das es Internet-Fans ermöglichte, das Team direkt zu managen. Das Stadion erhielt kürzlich massive moderne Renovierungen, um seine klassischen Terrassen auf den neuesten Stand zu bringen."
