      "fr": "Ce stade profondément historique du Lancashire possède un nom incroyablement unique et très intimidant dérivant de la forme originale de ses murs extérieurs. L'équipe locale passionnément soutenue porte du bleu pur et prétend fièrement avoir occupé ce terrain en continu depuis 1905. Ce lieu classique est remarquablement proche d'un immense château local historiquement célèbre.",
      "de": "Dieses zutiefst historische Stadion in Lancashire rühmt sich eines unglaublich einzigartigen, sehr einschüchternden Namens, der sich von der ursprünglichen Form seiner Außenmauern ableitet. Das leidenschaftlich unterstützte Heimteam trägt reines Blau und behauptet stolz, genau diesen Platz seit 1905 ununterbrochen belegt zu haben. Der klassische Veranstaltungsort liegt einzigartig nah an einer massiven, historisch berühmten lokalen Burg."
