      "de": "Dieser höchst legendäre historische Trainingsplatz war bis zum Jahr 2000 der Hauptstützpunkt eines globalen rot gekleideten Fußballgiganten. Er ist weltweit berühmt für die Entwicklung der ikonischen 'Class of 92'-Superstar-Generation. Der Veranstaltungsort behält bezeichnenderweise seine klassischen Flutlichter bei und wird noch heute aktiv für Jugendspiele genutzt."
